package com.taller.portal.service;
import com.taller.portal.dto.AuthDtos.*; import com.taller.portal.model.*; import com.taller.portal.repository.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*; import java.util.concurrent.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
/** Implementa recuperación de contraseña con OTP de un solo uso y caducidad limitada. */
@Service public class PasswordRecoveryService {
 private static final Duration CADUCIDAD=Duration.ofMinutes(15),VENTANA=Duration.ofMinutes(15); private static final int MAX_INTENTOS=5,MAX_SOLICITUDES=3; private final UserRepository users; private final PasswordResetTokenRepository tokens; private final PasswordEncoder encoder; private final NotificadorRecuperacion notificador; private final SecureRandom random=new SecureRandom(); private final ConcurrentMap<String,Deque<Instant>> rate=new ConcurrentHashMap<>();
 public PasswordRecoveryService(UserRepository users,PasswordResetTokenRepository tokens,PasswordEncoder encoder,NotificadorRecuperacion notificador){this.users=users;this.tokens=tokens;this.encoder=encoder;this.notificador=notificador;}
 /** Solicita un código sin revelar si existe la cuenta. */ @Transactional public void request(RecoveryRequest in,String ip){String id=normalizar(in.identificador());if(!permitir(id+"|"+ip))return;users.findByEmailOrCelular(id,in.identificador().trim()).ifPresent(user->{String code=String.format("%06d",random.nextInt(1_000_000));PasswordResetToken token=new PasswordResetToken();token.usuario=user;token.tokenHash=hash(code);token.expiraEn=LocalDateTime.now().plus(CADUCIDAD);tokens.save(token);notificador.notificar(user,code);});}
 /** Confirma un código válido, cambia la contraseña e invalida todos los códigos pendientes. */ @Transactional public void confirm(RecoveryConfirm in){String raw=in.identificador().trim(),id=normalizar(raw);User user=users.findByEmailOrCelular(id,raw).orElseThrow(()->new IllegalArgumentException("Código o solicitud inválidos"));PasswordResetToken token=tokens.findFirstByUsuarioAndUsadoEnIsNullOrderByCreadoEnDesc(user).orElseThrow(()->new IllegalArgumentException("Código o solicitud inválidos"));if(token.expiraEn.isBefore(LocalDateTime.now())||token.intentos>=MAX_INTENTOS)throw new IllegalArgumentException("Código o solicitud inválidos");token.intentos++;if(!MessageDigest.isEqual(token.tokenHash.getBytes(StandardCharsets.UTF_8),hash(in.token()).getBytes(StandardCharsets.UTF_8))){tokens.save(token);throw new IllegalArgumentException("Código o solicitud inválidos");}user.passwordHash=encoder.encode(in.nuevaPassword());users.save(user);tokens.invalidarPendientes(user);}
 private boolean permitir(String key){Deque<Instant> q=rate.computeIfAbsent(key,k->new ConcurrentLinkedDeque<>());Instant limite=Instant.now().minus(VENTANA);synchronized(q){while(!q.isEmpty()&&q.peekFirst().isBefore(limite))q.removeFirst();if(q.size()>=MAX_SOLICITUDES)return false;q.addLast(Instant.now());return true;}}
 private String normalizar(String value){return value.trim().toLowerCase(Locale.ROOT);} private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
